17	// pathChanCap holds a whole trace: every hop (at most MaxHopsLimit), the
18	// resolved message and the done message. The producer therefore never waits
19	// for a reader.
20	const pathChanCap = nettrace.MaxHopsLimit + 2
21	
22	// pathEngine is the seam between the path tab and the network: tests replace
23	// it with a fake.
24	type pathEngine struct {
25		supported func() error
26		resolve   func(ctx context.Context, host string) ([]netip.Addr, error)
27		route     func(ctx context.Context, a netip.Addr) (netcheck.RouteHop, error)
28		trace     func(ctx context.Context, a netip.Addr, o nettrace.Options, onHop func(nettrace.Hop)) (nettrace.Result, error)
29	}
30	
31	// systemPathEngine returns the engine backed by the real resolver and sockets.
32	func systemPathEngine() pathEngine {
33		env := netcheck.SystemEnv(netcheck.DefaultSettings())
34		return pathEngine{
35			supported: nettrace.Supported,
36			resolve: func(ctx context.Context, host string) ([]netip.Addr, error) {
37				return net.DefaultResolver.LookupNetIP(ctx, "ip4", host)
38			},
39			route: func(ctx context.Context, a netip.Addr) (netcheck.RouteHop, error) {
40				return env.Route(ctx, net.IP(a.AsSlice()))
41			},
42			trace: nettrace.TraceEach,
43		}
44	}
45	
46	// pathResolvedMsg reports the address the target resolved to.
47	type pathResolvedMsg struct {
48		gen      int
49		addr     netip.Addr
50		route    netcheck.RouteHop
51		routeErr error
52	}
53	
54	// pathHopMsg carries one hop as the engine reports it.
55	type pathHopMsg struct {
56		gen int
57		hop nettrace.Hop
58	}
59	
60	// pathDoneMsg ends a run: a result, or an error when no trace happened.
61	type pathDoneMsg struct {
62		gen    int
63		result nettrace.Result
64		err    error
65	}
66	
67	// producePath resolves the target, traces it and sends the messages to out,
68	// then closes out. It runs inside a Cmd and touches no model (Rule 110).
69	// out must have room for pathChanCap messages: sends never block, so a view
70	// that stops reading after canceling leaks nothing.
71	func producePath(ctx context.Context, gen int, tg pathTarget, resolveTimeout time.Duration, e pathEngine, out chan tea.Msg) {
72		defer close(out)
73		send := func(m tea.Msg) {
74			select {
75			case out <- m:
76			default:
77			}
78		}
79		// sendDone must never be lost: when the channel is full the oldest message
80		// is dropped to make room. The producer is the only sender, so one drop
81		// frees a slot for good.
82		sendDone := func(m tea.Msg) {
83			for range 2 {
84				select {
85				case out <- m:
86					return
87				default:
88				}
89				select {
90				case <-out:
91				default:
92				}
93			}
94		}
95	
96		addr, err := resolvePathTarget(ctx, tg.Host, resolveTimeout, e)
97		if err != nil {
98			if ctx.Err() == nil { // esc during the resolution is not an error
99				log.Printf("ERROR [netdiag/path] resolve %s: %v", tg.Host, err)
100			}
101			sendDone(pathDoneMsg{gen: gen, err: err})
102			return
103		}
104		// The route is asked for the address actually traced. A failure is not
105		// fatal and is never shown: the trace goes on without the route column.
106		route, routeErr := e.route(ctx, addr)
107		if routeErr != nil && ctx.Err() == nil {
108			log.Printf("ERROR [netdiag/path] route %s: %v", tg.Host, routeErr)
109		}
110		send(pathResolvedMsg{gen: gen, addr: addr, route: route, routeErr: routeErr})
111	
112		res, err := e.trace(ctx, addr, nettrace.Options{}, func(h nettrace.Hop) {
113			send(pathHopMsg{gen: gen, hop: h})
114		})
115		if err != nil {
116			log.Printf("ERROR [netdiag/path] trace %s: %v", tg.Host, err)
117		}
118		sendDone(pathDoneMsg{gen: gen, result: res, err: err})
119	}
120	
121	// resolvePathTarget returns the IPv4 address to trace: a literal is used as
122	// is, a name is resolved under its own timeout.
123	func resolvePathTarget(ctx context.Context, host string, timeout time.Duration, e pathEngine) (netip.Addr, error) {
124		if a, err := netip.ParseAddr(host); err == nil && a.Is4() {
125			return a, nil
126		}
127		rctx, cancel := context.WithTimeout(ctx, timeout)
128		defer cancel()
129		addrs, err := e.resolve(rctx, host)
130		if err != nil {
131			return netip.Addr{}, fmt.Errorf("%w: %w", errPathResolve, err)
132		}
133		if len(addrs) == 0 {
134			return netip.Addr{}, errPathNoIPv4
135		}
136		return addrs[0], nil
137	}
138	
139	// waitForPathMsg returns a Cmd that yields the next message of in, or nil
140	// once in is closed. The view re-arms it after every message.
141	func waitForPathMsg(in <-chan tea.Msg) tea.Cmd {
142		return func() tea.Msg {
143			m, ok := <-in
144			if !ok {
145				return nil
146			}
147			return m
148		}
149	}
